root=\"/work1/zixuan/outputs/agent_memory/pilot\"
fam_arch={q[\"family_idx\"]:q[\"archetype\"] for q in map(json.loads,open(\"/work1/zixuan/data/agent_memory/sealed/families.jsonl\"))}
for model in [\"qwen7b\",\"qwen3b\"]:
 rr=[]
 for p in sorted(glob.glob(root+\"/rollouts_\"+model+\"_shard*-of-*.jsonl\")): rr += list(map(json.loads,open(p)))
 print(model,\"rows\",len(rr),\"cells\",dict(collections.Counter(r[\"meta\"][\"cell\"] for r in rr)))
 tab={(r[\"meta\"][\"family_idx\"],r[\"meta\"][\"sibling_idx\"],r[\"meta\"][\"seed\"],r[\"meta\"][\"cell\"]):int(r[\"success\"]) for r in rr}
 ns=sum(v for k,v in tab.items() if k[3]==\"N\")
 print(\"unique\",len(tab),\"Nsuccess\",ns)
 for cell in [\"A11\",\"A10\",\"A01\",\"A00\"]:
  vals=[]; harm=[]; help=[]
  for fi in range(40):
   for si in range(4):
    for sd in range(4):
     n=tab[(fi,si,sd,\"N\")]; a=tab[(fi,si,sd,cell)]; vals.append(a-n); harm.append(n==1 and a==0); help.append(n==0 and a==1)
  print(cell,\"uplift_count\",sum(vals),\"uplift\",round(np.mean(vals),6),\"harm\",sum(harm),\"uncond\",round(np.mean(harm),6),\"cond\",round(sum(harm)/ns,6),\"help\",sum(help),\"help_uncond\",round(np.mean(help),6))
 print(\"A01 by archetype\")
 for arch in sorted(set(fam_arch.values())):
  fs=[fi for fi,a in fam_arch.items() if a==arch]; v=[];h=[];hp=[];nsa=0
  for fi in fs:
   for si in range(4):
    for sd in range(4):
     n=tab[(fi,si,sd,\"N\")]; a=tab[(fi,si,sd,\"A01\")]; nsa+=n;v.append(a-n);h.append(n==1 and a==0);hp.append(n==0 and a==1)
  print(arch,\"families\",len(fs),\"uplift\",round(np.mean(v),4),\"harm\",sum(h),\"uncond\",round(np.mean(h),4),\"cond\",round(sum(h)/nsa,4),\"help\",sum(hp),\"help_uncond\",round(np.mean(hp),4))
 rng=np.random.default_rng(20260810);B=50000;samples=rng.integers(0,40,size=(B,40))
 def fm(cell,kind):
  out=[]
  for fi in range(40):
   ar=[]
   for si in range(4):
    for sd in range(4):
     n=tab[(fi,si,sd,\"N\")];a=tab[(fi,si,sd,cell)];ar.append(a-n if kind==\"uplift\" else int(n==1 and a==0))
   out.append(np.mean(ar))
  return np.array(out)
 def boot(arr):
  z=arr[samples].mean(axis=1);return tuple(round(float(x),6) for x in [np.quantile(z,.025),np.quantile(z,.975),2*min(np.mean(z<=0),np.mean(z>=0))])
 for label,arr in [(\"A01 uplift\",fm(\"A01\",\"uplift\")),(\"A10-A01 uplift\",fm(\"A10\",\"uplift\")-fm(\"A01\",\"uplift\")),(\"A01-A11 harm\",fm(\"A01\",\"harm\")-fm(\"A11\",\"harm\")),(\"A01-A10 harm\",fm(\"A01\",\"harm\")-fm(\"A10\",\"harm\"))]: print(\"BOOT\",label,\"point\",round(float(arr.mean()),6),\"CIlo_CIhi_p\",boot(arr))
 print()'"

